-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        source_record_id,
        source_fund_id,
        source_cash_flow_on,
        source_cash_flow_type,
        source_direction,
        source_amount_usd,
        source_currency,
        cash_flow_source_system,
        violation_00,
        violation_01
    from {{ ref("investment__fund_cash_flow_conformed__checked") }}
),
violations as (
    select
        'source_record_id_not_null' as rule_name,
        source_record_id,
        source_fund_id,
        source_cash_flow_on,
        source_cash_flow_type,
        source_direction,
        source_amount_usd,
        source_currency,
        cash_flow_source_system
    from quarantined
    where violation_00

    union all

    select
        'source_cash_flow_on_not_null' as rule_name,
        source_record_id,
        source_fund_id,
        source_cash_flow_on,
        source_cash_flow_type,
        source_direction,
        source_amount_usd,
        source_currency,
        cash_flow_source_system
    from quarantined
    where violation_01
)

select
    rule_name,
    source_record_id,
    source_fund_id,
    source_cash_flow_on,
    source_cash_flow_type,
    source_direction,
    source_amount_usd,
    source_currency,
    cash_flow_source_system
from violations
